function monthsOld(birthDate:string){return Math.max(0,Math.floor((Date.now()-new Date(`${birthDate}T12:00:00`).getTime())/(1000*60*60*24*30.4375)))}

function AllergenDialog({open,onOpenChange,onSave}:{open:boolean;onOpenChange:(open:boolean)=>void;onSave:(payload:{name:string;hint:string;emoji:string})=>Promise<boolean>}){
  const[emoji,setEmoji]=useState(foodEmojis[0]),[saving,setSaving]=useState(false);
  useEffect(()=>{if(open)setEmoji(foodEmojis[0])},[open]);
  async function submit(event:React.FormEvent<HTMLFormElement>){event.preventDefault();setSaving(true);const data=new FormData(event.currentTarget),saved=await onSave({name:String(data.get("name")??"").trim(),hint:String(data.get("hint")??"").trim(),emoji});setSaving(false);if(saved)onOpenChange(false)}
  return <Dialog open={open} onOpenChange={value=>{if(!saving)onOpenChange(value)}}><DialogContent className="max-h-[92vh] overflow-y-auto sm:max-w-xl"><form onSubmit={submit} className="grid gap-5"><DialogHeader><DialogTitle className="font-display text-2xl">Añadir alimento</DialogTitle><DialogDescription>Crea un seguimiento de tres días para cualquier alimento que quieras introducir. Sus checks serán independientes para cada bebé.</DialogDescription></DialogHeader><div className="grid gap-4"><div className="grid gap-2"><Label htmlFor="allergen-name">Alimento</Label><Input id="allergen-name" name="name" maxLength={60} required placeholder="Ej. Kiwi"/></div><div className="grid gap-2"><Label htmlFor="allergen-hint">Cómo ofrecerlo o qué observar</Label><Textarea id="allergen-hint" name="hint" rows={3} maxLength={160} placeholder="Ej. Maduro, pelado y en una textura segura"/></div><fieldset><legend className="text-sm font-medium">Elige un icono</legend><div className="mt-2 grid gap-3">{foodEmojiGroups.map(group=><div key={group.label}><p className="mb-1.5 text-xs font-bold uppercase tracking-wide text-[#708496]">{group.label}</p><div className="grid grid-cols-8 gap-2">{group.icons.map(option=><button key={option} type="button" aria-label={`Usar ${option}`} aria-pressed={emoji===option} onClick={()=>setEmoji(option)} className={`grid aspect-square min-h-10 place-items-center rounded-xl border text-xl transition ${emoji===option?"border-[#087f8c] bg-[#eaf7f6] shadow-sm ring-2 ring-[#087f8c]/20":"border-[#dfe8ef] bg-white hover:border-[#9ec8d1]"}`}>{option}</button>)}</div></div>)}</div></fieldset><div className="flex items-center gap-3 rounded-2xl bg-[#f7fafb] p-3"><span className="grid size-11 shrink-0 place-items-center rounded-2xl bg-[#fff5e6] text-xl">{emoji}</span><div><p className="text-sm font-bold">Así se verá en el seguimiento</p><p className="text-xs text-[#708496]">Mantendrá el mismo estilo visual que los alimentos principales.</p></div></div></div><DialogFooter><Button type="button" variant="outline" onClick={()=>onOpenChange(false)} disabled={saving}>Cancelar</Button><Button type="submit" disabled={saving} className="bg-[#087f8c] text-white hover:bg-[#066b76]"><Plus size={17}/>{saving?"Añadiendo…":"Añadir alimento"}</Button></DialogFooter></form></DialogContent></Dialog>
}

function ExposureDatesDialog({open,allergen,records,onOpenChange,onSave}:{open:boolean;allergen:FoodAllergen|null;records:FoodExposure[];onOpenChange:(open:boolean)=>void;onSave:(dates:{dayIndex:number;exposedAt:string}[])=>Promise<boolean>}){
  const[saving,setSaving]=useState(false);
  async function submit(event:React.FormEvent<HTMLFormElement>){
    event.preventDefault();
    const data=new FormData(event.currentTarget),dates=records.map(record=>({dayIndex:record.dayIndex,exposedAt:String(data.get(`day-${record.dayIndex}`)??"")}));
    const values=dates.map(item=>item.exposedAt);
    if(new Set(values).size!==values.length){toast.error("Cada día debe tener una fecha distinta.");return}
    if(values.some((value,index)=>index>0&&value<values[index-1])){toast.error("Las fechas deben seguir el orden de los días.");return}
    setSaving(true);const saved=await onSave(dates);setSaving(false);if(saved)onOpenChange(false);
  }
  return <Dialog open={open} onOpenChange={value=>{if(!saving)onOpenChange(value)}}><DialogContent className="sm:max-w-md"><form key={`${allergen?.id}-${records.map(record=>`${record.dayIndex}:${record.exposedAt}`).join("|")}`} onSubmit={submit} className="grid gap-5"><DialogHeader><DialogTitle className="font-display text-2xl">Editar fechas</DialogTitle><DialogDescription>Corrige los días registrados para {allergen?.name}. Cada exposición debe corresponder a una fecha distinta.</DialogDescription></DialogHeader><div className="grid gap-3">{records.map(record=><div key={record.dayIndex} className="grid gap-2"><Label htmlFor={`exposure-day-${record.dayIndex}`}>Día {record.dayIndex}</Label><Input id={`exposure-day-${record.dayIndex}`} name={`day-${record.dayIndex}`} type="date" max={today()} defaultValue={record.exposedAt} required/></div>)}</div><DialogFooter><Button type="button" variant="outline" onClick={()=>onOpenChange(false)} disabled={saving}>Cancelar</Button><Button type="submit" disabled={saving} className="bg-[#087f8c] text-white hover:bg-[#066b76]">{saving?"Guardando…":"Guardar fechas"}</Button></DialogFooter></form></DialogContent></Dialog>
}

function RecipeDialog({open,recipe,onOpenChange,onSave}:{open:boolean;recipe:CustomRecipe|null;onOpenChange:(open:boolean)=>void;onSave:(payload:RecipePayload)=>Promise<boolean>}){
  const[saving,setSaving]=useState(false);
  async function submit(event:React.FormEvent<HTMLFormElement>){
    event.preventDefault();setSaving(true);
    const data=new FormData(event.currentTarget),ingredients=String(data.get("ingredients")??"").split(/\r?\n|,/).map(value=>value.trim()).filter(Boolean);
    const saved=await onSave({title:String(data.get("title")??"").trim(),minAgeMonths:Number(data.get("minAgeMonths")),timeMinutes:Number(data.get("timeMinutes")),ingredients,preparation:String(data.get("preparation")??"").trim(),allergens:data.getAll("allergens").map(String)});
    setSaving(false);if(saved)onOpenChange(false);
  }
  return <Dialog open={open} onOpenChange={value=>{if(!saving)onOpenChange(value)}}><DialogContent className="max-h-[92vh] overflow-y-auto sm:max-w-2xl"><form key={recipe?.id??"new"} onSubmit={submit} className="grid gap-5"><DialogHeader><DialogTitle className="font-display text-2xl">{recipe?"Editar receta":"Añadir una receta BLW"}</DialogTitle><DialogDescription>Se guardará en tu recetario y estará disponible desde cualquier perfil de bebé.</DialogDescription></DialogHeader><div className="grid gap-4 sm:grid-cols-2"><div className="grid gap-2 sm:col-span-2"><Label htmlFor="recipe-title">Nombre de la receta</Label><Input id="recipe-title" name="title" defaultValue={recipe?.title} maxLength={100} required placeholder="Ej. Tortitas de calabacín"/></div><div className="grid gap-2"><Label htmlFor="recipe-age">Edad recomendada</Label><select id="recipe-age" name="minAgeMonths" defaultValue={recipe?.minAgeMonths??6} className="h-9 rounded-md border border-input bg-transparent px-3 text-sm shadow-xs outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50">{[6,7,8,9,12].map(month=><option key={month} value={month}>{month}+ meses</option>)}</select></div><div className="grid gap-2"><Label htmlFor="recipe-time">Tiempo aproximado (min)</Label><Input id="recipe-time" name="timeMinutes" type="number" min={1} max={240} defaultValue={recipe?.timeMinutes??20} required/></div><div className="grid gap-2 sm:col-span-2"><Label htmlFor="recipe-ingredients">Ingredientes</Label><Textarea id="recipe-ingredients" name="ingredients" defaultValue={recipe?.ingredients.join("\n")} rows={4} required placeholder={"Un ingrediente por línea\nCalabacín\nHuevo\nHarina de avena"}/><p className="text-xs text-muted-foreground">Escribe un ingrediente por línea (máximo 20).</p></div><div className="grid gap-2 sm:col-span-2"><Label htmlFor="recipe-preparation">Preparación y presentación segura</Label><Textarea id="recipe-preparation" name="preparation" defaultValue={recipe?.preparation} rows={4} maxLength={1000} required placeholder="Explica cómo prepararla, cocinarla y ofrecerla con una textura segura."/></div><fieldset className="sm:col-span-2"><legend className="text-sm font-medium">Alérgenos que contiene</legend><div className="mt-2 grid grid-cols-2 gap-2 sm:grid-cols-3">{recipeAllergens.map(allergen=><label key={allergen} className="flex min-h-10 cursor-pointer items-center gap-2 rounded-xl border border-[#dfe8ef] px-3 text-sm"><input name="allergens" type="checkbox" value={allergen} defaultChecked={recipe?.allergens.includes(allergen)} className="size-4 accent-[#087f8c]"/><span>{allergen}</span></label>)}</div></fieldset></div><DialogFooter><Button type="button" variant="outline" onClick={()=>onOpenChange(false)} disabled={saving}>Cancelar</Button><Button type="submit" disabled={saving} className="bg-[#f06449] text-white hover:bg-[#d9573f]">{saving?"Guardando…":recipe?"Guardar cambios":"Añadir receta"}</Button></DialogFooter></form></DialogContent></Dialog>
}

function EquivalenceDialog({open,onOpenChange,onSave}:{open:boolean;onOpenChange:(open:boolean)=>void;onSave:(payload:EquivalencePayload)=>Promise<boolean>}){
  const[saving,setSaving]=useState(false);
  async function submit(event:React.FormEvent<HTMLFormElement>){event.preventDefault();setSaving(true);const data=new FormData(event.currentTarget),saved=await onSave({title:String(data.get("title")??"").trim(),milkMl:Number(data.get("milkMl")),productAmount:Number(data.get("productAmount")),productUnit:String(data.get("productUnit")??"").trim()});setSaving(false);if(saved)onOpenChange(false)}
  return <Dialog open={open} onOpenChange={value=>{if(!saving)onOpenChange(value)}}><DialogContent className="sm:max-w-lg"><form key={open?"open":"closed"} onSubmit={submit} className="grid gap-5"><DialogHeader><DialogTitle className="font-display text-2xl">Nueva equivalencia</DialogTitle><DialogDescription>Introduce la proporción indicada en el producto. Calcularemos automáticamente las cantidades para biberones de 30 a 300 ml.</DialogDescription></DialogHeader><div className="grid gap-4"><div className="grid gap-2"><Label htmlFor="equivalence-title">Título</Label><Input id="equivalence-title" name="title" maxLength={100} required placeholder="Ej. Cereales de arroz"/></div><div className="grid gap-4 sm:grid-cols-2"><div className="grid gap-2"><Label htmlFor="equivalence-milk">Cantidad de leche (ml)</Label><Input id="equivalence-milk" name="milkMl" type="number" min="0.001" max="10000" step="any" inputMode="decimal" required placeholder="Ej. 150"/></div><div className="grid gap-2"><Label htmlFor="equivalence-product">Cantidad de producto</Label><Input id="equivalence-product" name="productAmount" type="number" min="0.001" max="10000" step="any" inputMode="decimal" required placeholder="Ej. 5"/></div></div><div className="grid gap-2"><Label htmlFor="equivalence-unit">Unidad del producto</Label><Input id="equivalence-unit" name="productUnit" maxLength={30} required placeholder="Ej. g, mg, ml, cacitos…"/><p className="text-xs text-muted-foreground">La unidad es libre para respetar exactamente las indicaciones del envase.</p></div></div><DialogFooter><Button type="button" variant="outline" onClick={()=>onOpenChange(false)} disabled={saving}>Cancelar</Button><Button type="submit" disabled={saving} className="bg-[#087f8c] text-white hover:bg-[#066b76]"><Calculator size={17}/>{saving?"Calculando…":"Crear tabla"}</Button></DialogFooter></form></DialogContent></Dialog>
}

export default function FoodTracker({child,exposures,onChange}:{child:FoodChild;exposures:FoodExposure[];onChange:(next:FoodExposure[])=>void}){
  const[section,setSection]=useState<"allergens"|"guide"|"recipes"|"equivalences">("allergens"),[showAll,setShowAll]=useState(false),[saving,setSaving]=useState(""),[recipeAge,setRecipeAge]=useState<number|"all">(6),[recipeSearch,setRecipeSearch]=useState("");
  const[customRecipes,setCustomRecipes]=useState<CustomRecipe[]>([]),[recipeDialogOpen,setRecipeDialogOpen]=useState(false),[editingRecipe,setEditingRecipe]=useState<CustomRecipe|null>(null),[deletingRecipe,setDeletingRecipe]=useState<CustomRecipe|null>(null),[deleting,setDeleting]=useState(false);
  const[customAllergens,setCustomAllergens]=useState<CustomAllergen[]>([]),[hiddenAllergenIds,setHiddenAllergenIds]=useState<string[]>([]),[allergenDialogOpen,setAllergenDialogOpen]=useState(false),[editingDates,setEditingDates]=useState<FoodAllergen|null>(null),[deletingAllergen,setDeletingAllergen]=useState<FoodAllergen|null>(null),[deletingAllergenBusy,setDeletingAllergenBusy]=useState(false);
  const[equivalences,setEquivalences]=useState<FeedingEquivalence[]>([]),[equivalenceDialogOpen,setEquivalenceDialogOpen]=useState(false),[deletingEquivalence,setDeletingEquivalence]=useState<FeedingEquivalence|null>(null),[deletingEquivalenceBusy,setDeletingEquivalenceBusy]=useState(false);
  const childExposures=useMemo(()=>exposures.filter(item=>item.childId===child.id),[exposures,child.id]);
  const allergenCatalog=useMemo<FoodAllergen[]>(()=>[...customAllergens.map(item=>({...item,common:true})),...defaultAllergens.filter(item=>!hiddenAllergenIds.includes(item.id))],[customAllergens,hiddenAllergenIds]);
  const displayedAllergens=useMemo(()=>allergenCatalog.filter(allergen=>showAll||allergen.common||allergen.custom).map((allergen,index)=>{const records=childExposures.filter(item=>item.allergenId===allergen.id).sort((a,b)=>a.dayIndex-b.dayIndex),latest=records.reduce((value,item)=>Math.max(value,Date.parse(item.createdAt??`${item.exposedAt}T12:00:00`)),0);return{allergen,records,index,latest}}).sort((a,b)=>(b.records.length>0?1:0)-(a.records.length>0?1:0)||b.latest-a.latest||a.index-b.index),[allergenCatalog,childExposures,showAll]);
  const age=monthsOld(child.birthDate),recommendedAge=age>=12?12:age>=9?9:age>=8?8:age>=7?7:6;
  useEffect(()=>{setRecipeAge(recommendedAge);setRecipeSearch("")},[child.id,recommendedAge]);
  useEffect(()=>{let active=true;void fetch(api("/api/recipes")).then(async response=>{const out=await response.json() as {recipes?:CustomRecipe[];error?:string};if(!response.ok)throw new Error(out.error);if(active)setCustomRecipes(out.recipes??[])}).catch(()=>{if(active)toast.error("No se ha podido cargar tu recetario personal.")});return()=>{active=false}},[]);
  useEffect(()=>{let active=true;void fetch(api("/api/allergens")).then(async response=>{const out=await response.json() as {custom?:CustomAllergen[];hiddenIds?:string[];error?:string};if(!response.ok)throw new Error(out.error);if(active){setCustomAllergens(out.custom??[]);setHiddenAllergenIds(out.hiddenIds??[])}}).catch(()=>{if(active)toast.error("No se ha podido cargar tu lista de alimentos.")});return()=>{active=false}},[]);
  useEffect(()=>{let active=true;void fetch(api("/api/feeding-equivalences")).then(async response=>{const out=await response.json() as {equivalences?:FeedingEquivalence[];error?:string};if(!response.ok)throw new Error(out.error);if(active)setEquivalences(out.equivalences??[])}).catch(()=>{if(active)toast.error("No se han podido cargar tus equivalencias.")});return()=>{active=false}},[]);
  const recipeCatalog=useMemo<DisplayRecipe[]>(()=>[
    ...customRecipes.map(recipe=>({key:recipe.id,id:recipe.id,custom:true,min:recipe.minAgeMonths,title:recipe.title,time:`${recipe.timeMinutes} min`,ingredients:recipe.ingredients.join(", "),allergens:recipe.allergens,text:recipe.preparation})),
    ...recipes.map((recipe,index)=>({key:`suggested-${index}`,custom:false,...recipe})),
  ],[customRecipes]);
  const availableRecipes=recipeCatalog.filter(recipe=>(recipeAge==="all"||recipe.min===recipeAge)&&(!recipeSearch.trim()||`${recipe.title} ${recipe.ingredients} ${recipe.allergens.join(" ")}`.toLocaleLowerCase("es-ES").includes(recipeSearch.trim().toLocaleLowerCase("es-ES"))));
  async function saveRecipe(payload:RecipePayload){
    try{const response=await fetch(api(editingRecipe?`/api/recipes/${editingRecipe.id}`:"/api/recipes"),{method:editingRecipe?"PATCH":"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)}),out=await response.json() as {recipe?:CustomRecipe;error?:string};if(!response.ok||!out.recipe)throw new Error(out.error??"No se ha podido guardar.");setCustomRecipes(current=>editingRecipe?current.map(recipe=>recipe.id===out.recipe!.id?out.recipe!:recipe):[out.recipe!,...current]);toast.success(editingRecipe?"Receta actualizada":"Receta añadida a tu recetario");return true}catch(error){toast.error(error instanceof Error?error.message:"No se ha podido guardar.");return false}
  }
  async function deleteRecipe(){
    if(!deletingRecipe)return;setDeleting(true);try{const response=await fetch(api(`/api/recipes/${deletingRecipe.id}`),{method:"DELETE"}),out=await response.json() as {error?:string};if(!response.ok)throw new Error(out.error??"No se ha podido eliminar.");setCustomRecipes(current=>current.filter(recipe=>recipe.id!==deletingRecipe.id));setDeletingRecipe(null);toast.success("Receta eliminada")}catch(error){toast.error(error instanceof Error?error.message:"No se ha podido eliminar.")}finally{setDeleting(false)}
  }
  async function saveAllergen(payload:{name:string;hint:string;emoji:string}){
    try{const response=await fetch(api("/api/allergens"),{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)}),out=await response.json() as {allergen?:CustomAllergen;error?:string};if(!response.ok||!out.allergen)throw new Error(out.error??"No se ha podido añadir.");setCustomAllergens(current=>[out.allergen!,...current]);setShowAll(true);toast.success(`${out.allergen.name} añadido al seguimiento`);return true}catch(error){toast.error(error instanceof Error?error.message:"No se ha podido añadir.");return false}
  }
  async function deleteAllergen(){
    if(!deletingAllergen)return;setDeletingAllergenBusy(true);try{const response=await fetch(api(`/api/allergens/${deletingAllergen.id}`),{method:"DELETE"}),out=await response.json() as {error?:string};if(!response.ok)throw new Error(out.error??"No se ha podido eliminar.");if(deletingAllergen.custom)setCustomAllergens(current=>current.filter(item=>item.id!==deletingAllergen.id));else setHiddenAllergenIds(current=>[...current,deletingAllergen.id]);onChange(exposures.filter(item=>item.allergenId!==deletingAllergen.id));toast.success(`${deletingAllergen.name} eliminado del seguimiento`);setDeletingAllergen(null)}catch(error){toast.error(error instanceof Error?error.message:"No se ha podido eliminar.")}finally{setDeletingAllergenBusy(false)}
  }
  async function saveEquivalence(payload:EquivalencePayload){
    try{const response=await fetch(api("/api/feeding-equivalences"),{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)}),out=await response.json() as {equivalence?:FeedingEquivalence;error?:string};if(!response.ok||!out.equivalence)throw new Error(out.error??"No se ha podido crear la tabla.");setEquivalences(current=>[out.equivalence!,...current]);toast.success("Tabla de equivalencias creada");return true}catch(error){toast.error(error instanceof Error?error.message:"No se ha podido crear la tabla.");return false}
  }
  async function deleteEquivalence(){
    if(!deletingEquivalence)return;setDeletingEquivalenceBusy(true);try{const response=await fetch(api(`/api/feeding-equivalences/${deletingEquivalence.id}`),{method:"DELETE"}),out=await response.json() as {error?:string};if(!response.ok)throw new Error(out.error??"No se ha podido eliminar.");setEquivalences(current=>current.filter(item=>item.id!==deletingEquivalence.id));setDeletingEquivalence(null);toast.success("Equivalencia eliminada")}catch(error){toast.error(error instanceof Error?error.message:"No se ha podido eliminar.")}finally{setDeletingEquivalenceBusy(false)}
  }
  async function toggle(allergenId:string,dayIndex:number,checked:boolean){
    const key=`${allergenId}-${dayIndex}`;
    if(checked){const previous=childExposures.find(item=>item.allergenId===allergenId&&item.dayIndex===dayIndex-1);if(dayIndex>1&&!previous)return;if(previous?.exposedAt===today()){toast.info("Marca una exposición por día para que el recuento represente días distintos.");return}}
    setSaving(key);
    try{const res=await fetch(api("/api/food-exposures"),{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({childId:child.id,allergenId,dayIndex,checked,exposedAt:today()})});const out=await res.json() as {error?:string;exposure?:FoodExposure|null};if(!res.ok)throw new Error(out.error??"No se ha podido guardar.");const without=exposures.filter(item=>!(item.childId===child.id&&item.allergenId===allergenId&&item.dayIndex===dayIndex));onChange(out.exposure?[...without,out.exposure]:without);toast.success(checked?`Día ${dayIndex} registrado`:"Check eliminado")}catch(error){toast.error(error instanceof Error?error.message:"No se ha podido guardar.")}finally{setSaving("")}
  }
  async function saveExposureDates(dates:{dayIndex:number;exposedAt:string}[]){
    if(!editingDates)return false;let next=exposures;
    try{for(const date of dates){const current=childExposures.find(item=>item.allergenId===editingDates.id&&item.dayIndex===date.dayIndex);if(current?.exposedAt===date.exposedAt)continue;const response=await fetch(api("/api/food-exposures"),{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({childId:child.id,allergenId:editingDates.id,dayIndex:date.dayIndex,checked:true,exposedAt:date.exposedAt})}),out=await response.json() as {error?:string;exposure?:FoodExposure};if(!response.ok||!out.exposure)throw new Error(out.error??"No se han podido guardar las fechas.");next=[...next.filter(item=>!(item.childId===child.id&&item.allergenId===editingDates.id&&item.dayIndex===date.dayIndex)),out.exposure]};onChange(next);toast.success("Fechas actualizadas");return true}catch(error){onChange(next);toast.error(error instanceof Error?error.message:"No se han podido guardar las fechas.");return false}
  }
  return <div className="mt-6">
    <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
      {([{id:"allergens",label:"Alérgenos",icon:ShieldAlert,sub:"Regla de 3 días"},{id:"guide",label:"Guía segura",icon:Info,sub:"OMS + AESAN"},{id:"recipes",label:"Recetas BLW",icon:ChefHat,sub:`Para ${age} meses`},{id:"equivalences",label:"Equivalencias",icon:Calculator,sub:"Biberones 30–300 ml"}] as const).map(item=><button key={item.id} onClick={()=>setSection(item.id)} className={`flex min-h-20 items-center gap-3 rounded-2xl border p-4 text-left transition ${section===item.id?"border-[#087f8c] bg-[#eaf7f6] shadow-sm":"border-[#dfe8ef] bg-white hover:border-[#9ec8d1]"}`}><span className={`grid size-10 shrink-0 place-items-center rounded-xl ${section===item.id?"bg-[#087f8c] text-white":"bg-[#eef3f6] text-[#527186]"}`}><item.icon size={20}/></span><span><strong className="block">{item.label}</strong><small className="text-[#708496]">{item.sub}</small></span></button>)}
    </div>
    {section==="allergens"&&<section className="mt-5">
      <div className="rounded-3xl bg-[#103f5c] p-5 text-white sm:p-6"><div className="flex flex-wrap items-end justify-between gap-4"><div><p className="text-xs font-bold tracking-widest text-[#9ec8d1]">SEGUIMIENTO DE {child.name.toUpperCase()}</p><h2 className="font-display mt-1 text-2xl font-bold">Introducción de alimentos</h2><p className="mt-2 max-w-2xl text-sm leading-relaxed text-[#d3e5e9]">Controla los alérgenos principales y cualquier otro alimento que quieras introducir. Cada uno conserva sus propios tres días por bebé.</p></div><div className="flex items-center gap-3"><div className="rounded-2xl bg-white/10 px-4 py-3 text-center"><strong className="font-display text-2xl">{allergenCatalog.filter(a=>childExposures.filter(e=>e.allergenId===a.id).length===3).length}/{allergenCatalog.length}</strong><span className="block text-xs text-[#cfe1e6]">completados</span></div><Button onClick={()=>setAllergenDialogOpen(true)} className="bg-white text-[#08717c] shadow-sm hover:bg-[#f3fbfb]"><Plus size={18}/>Añadir alimento</Button></div></div></div>
      <div className="mt-4 grid gap-3 lg:grid-cols-2">{displayedAllergens.map(({allergen,records:done})=><article key={allergen.id} className={`rounded-3xl border bg-white p-4 shadow-sm ${allergen.custom?"border-[#9ec8d1]":"border-[#dfe8ef]"}`}><div className="flex items-start gap-3"><span className="grid size-11 shrink-0 place-items-center rounded-2xl bg-[#fff5e6] text-xl">{allergen.emoji}</span><div className="min-w-0 flex-1"><div className="flex items-center justify-between gap-2"><div className="flex min-w-0 items-center gap-2"><h3 className="truncate font-bold">{allergen.name}</h3>{allergen.custom&&<Badge className="shrink-0 bg-[#eaf7f6] text-[#087f8c]">Añadido</Badge>}</div><div className="flex shrink-0 items-center gap-1">{done.length>0&&<button aria-label={`Editar fechas de ${allergen.name}`} title="Editar fechas" onClick={()=>setEditingDates(allergen)} className="grid size-8 place-items-center rounded-lg text-[#087f8c] transition hover:bg-[#eaf7f6]"><Pencil size={15}/></button>}<Badge className={done.length===3?"bg-[#dff3e8] text-[#17643a]":"bg-[#eef3f6] text-[#587084]"}>{done.length}/3 días</Badge><button aria-label={`Eliminar ${allergen.name}`} onClick={()=>setDeletingAllergen(allergen)} className="grid size-8 place-items-center rounded-lg text-[#8a9aa6] transition hover:bg-[#fff0ed] hover:text-[#b43d34]"><Trash2 size={15}/></button></div></div><p className="mt-0.5 text-xs text-[#708496]">{allergen.hint||"Seguimiento personalizado de tres días"}</p></div></div><Progress className="mt-4 h-1.5" value={done.length/3*100}/><div className="mt-3 grid grid-cols-3 gap-2">{[1,2,3].map(day=>{const record=done.find(item=>item.dayIndex===day),canUse=!!record||day===done.length+1,isSaving=saving===`${allergen.id}-${day}`;return <button key={day} disabled={!canUse||!!saving} onClick={()=>void toggle(allergen.id,day,!record)} className={`min-h-12 rounded-xl border px-2 text-xs font-bold transition disabled:cursor-not-allowed ${record?"border-[#78c09b] bg-[#e6f6ed] text-[#17643a]":"border-[#dfe8ef] bg-[#f8fafb] text-[#6f8395] disabled:opacity-45"}`}>{record?<><Check className="mx-auto mb-0.5" size={15}/>{dateText(record.exposedAt)}</>:isSaving?"Guardando…":`Día ${day}`}</button>})}</div></article>)}</div>
      <button onClick={()=>setShowAll(value=>!value)} className="mt-4 w-full rounded-2xl border border-dashed border-[#a9becb] bg-white p-3 text-sm font-bold text-[#087f8c]">{showAll?"Ver solo los alimentos más habituales y los añadidos":"Ver todos los alérgenos principales"}</button>
      <div className="mt-4 flex gap-3 rounded-2xl border border-[#f0d493] bg-[#fff9e9] p-4 text-sm leading-relaxed text-[#6d5520]"><CircleAlert className="mt-0.5 shrink-0" size={19}/><p><b>Seguridad:</b> si hay dificultad para respirar, hinchazón de lengua/labios, decaimiento intenso o síntomas generalizados, llama al 112. Con eczema grave, alergia conocida o reacción previa, consulta con pediatría/alergología antes de introducir nuevos alérgenos.</p></div>
    </section>}
    {section==="guide"&&<section className="mt-5"><div className="flex flex-wrap items-end justify-between gap-3"><div><p className="text-xs font-bold tracking-widest text-[#087f8c]">GUÍA GENERAL · NO CAMBIA ENTRE PERFILES</p><h2 className="font-display mt-1 text-2xl font-bold">Qué evitar y hasta cuándo</h2></div><Badge className="bg-[#eaf7f6] text-[#087f8c]">Revisada · oct 2026</Badge></div><p className="mt-2 max-w-3xl text-sm leading-relaxed text-[#63798b]">Resumen práctico basado en recomendaciones de OMS y organismos oficiales. Cada tarjeta enlaza directamente a su fuente; no sustituye las indicaciones de vuestro equipo pediátrico.</p><div className="mt-4 grid gap-3 lg:grid-cols-2">{guide.map(item=><article key={`${item.until}-${item.title}`} className="rounded-3xl border border-[#dfe8ef] bg-white p-5 shadow-sm"><div className="flex items-start justify-between gap-3"><Badge className="bg-[#fff0d5] text-[#7b5100]">{item.until==="Siempre"?"Evitar siempre":item.until==="0–23 meses"?"Durante 0–23 meses":`Hasta ${item.until}`}</Badge><a href={item.url} target="_blank" rel="noreferrer" className="inline-flex items-center gap-1 text-xs font-bold text-[#087f8c] hover:underline">{item.source}<ExternalLink size={13}/></a></div><h3 className="mt-3 font-display text-lg font-bold">{item.title}</h3><p className="mt-1.5 text-sm leading-relaxed text-[#64798a]">{item.text}</p></article>)}</div></section>}
    {section==="recipes"&&<section className="mt-5">
      <div className="rounded-3xl bg-gradient-to-br from-[#f06449] to-[#e08a55] p-5 text-white sm:p-6"><div className="flex flex-wrap items-end justify-between gap-4"><div><p className="text-xs font-bold tracking-widest text-white/75">TU RECETARIO FAMILIAR</p><h2 className="font-display mt-1 text-2xl font-bold">Ideas BLW para cada etapa</h2><p className="mt-2 max-w-2xl text-sm leading-relaxed text-white/90">Abrimos la etapa recomendada para los {age} meses de {child.name}, pero puedes explorar cualquier mes. Las recetas que añadas estarán disponibles en todos los perfiles.</p></div><Button onClick={()=>{setEditingRecipe(null);setRecipeDialogOpen(true)}} className="bg-white text-[#c84b37] shadow-sm hover:bg-[#fff7f3]"><Plus size={18}/>Añadir receta</Button></div></div>
      {age<6&&<div className="mt-4 flex gap-3 rounded-2xl border border-[#f0d493] bg-[#fff9e9] p-4 text-sm leading-relaxed text-[#6d5520]"><Utensils className="mt-0.5 shrink-0" size={19}/><p>Estas ideas son para preparar la siguiente etapa. La alimentación complementaria suele comenzar alrededor de los 6 meses, cuando se cumplen las señales de preparación.</p></div>}
      <div className="mt-4 rounded-3xl border border-[#dfe8ef] bg-white p-4 shadow-sm"><div className="flex flex-wrap items-center gap-2"><span className="mr-1 text-sm font-bold text-[#536b7d]">Explorar:</span>{([6,7,8,9,12] as const).map(month=><button key={month} onClick={()=>setRecipeAge(month)} className={`min-h-10 rounded-xl px-3 text-sm font-bold transition ${recipeAge===month?"bg-[#f06449] text-white shadow-sm":"bg-[#eef3f6] text-[#587084] hover:bg-[#e2eaef]"}`}>{month}+ meses {month===recommendedAge&&<span aria-label="Etapa recomendada">· Ahora</span>}</button>)}<button onClick={()=>setRecipeAge("all")} className={`min-h-10 rounded-xl px-3 text-sm font-bold transition ${recipeAge==="all"?"bg-[#f06449] text-white shadow-sm":"bg-[#eef3f6] text-[#587084] hover:bg-[#e2eaef]"}`}>Todas</button></div><label className="mt-3 flex min-h-11 items-center gap-2 rounded-xl border border-[#d7e1e7] bg-[#f9fbfc] px-3 text-[#718596]"><Search size={17}/><span className="sr-only">Buscar recetas</span><input value={recipeSearch} onChange={event=>setRecipeSearch(event.target.value)} className="min-w-0 flex-1 bg-transparent text-sm text-[#17324d] outline-none placeholder:text-[#8b9ba7]" placeholder="Buscar por receta, ingrediente o alérgeno…"/></label></div>
      <div className="mt-4 flex items-center justify-between gap-3"><p className="text-sm text-[#708496]"><b className="text-[#17324d]">{availableRecipes.length}</b> {availableRecipes.length===1?"receta":"recetas"}{recipeAge!=="all"&&recipeAge>recommendedAge?" para descubrir más adelante":""}</p>{recipeAge!==recommendedAge&&<button onClick={()=>setRecipeAge(recommendedAge)} className="text-sm font-bold text-[#087f8c] hover:underline">Volver a su etapa</button>}</div>
      {availableRecipes.length?<div className="mt-3 grid gap-4 lg:grid-cols-2">{availableRecipes.map(recipe=><article key={recipe.key} className={`rounded-3xl border bg-white p-5 shadow-sm ${recipe.custom?"border-[#f2b09f]":"border-[#dfe8ef]"}`}><div className="flex items-start justify-between gap-3"><span className="grid size-10 place-items-center rounded-xl bg-[#fff0e8] text-[#d9573f]"><ChefHat size={20}/></span><div className="flex flex-wrap justify-end gap-2">{recipe.custom&&<Badge className="bg-[#fff0e8] text-[#b94532]">Mi receta</Badge>}<Badge className="bg-[#eef7f7] text-[#087f8c]">{recipe.min}+ meses</Badge><Badge variant="outline">{recipe.time}</Badge></div></div><h3 className="font-display mt-4 text-xl font-bold">{recipe.title}</h3><p className="mt-1 text-sm font-semibold text-[#465f72]">{recipe.ingredients}</p><p className="mt-2 text-sm leading-relaxed text-[#708496]">{recipe.text}</p>{recipe.allergens.length>0&&<div className="mt-3 flex flex-wrap gap-1.5">{recipe.allergens.map(allergen=><Badge key={allergen} className="bg-[#fff5df] text-[#7b5708]">Contiene {allergen}</Badge>)}</div>}{recipe.custom&&<div className="mt-4 flex gap-2 border-t border-[#edf1f4] pt-3"><Button variant="outline" size="sm" onClick={()=>{const source=customRecipes.find(item=>item.id===recipe.id);if(source){setEditingRecipe(source);setRecipeDialogOpen(true)}}}><Pencil size={15}/>Editar</Button><Button variant="ghost" size="sm" onClick={()=>{const source=customRecipes.find(item=>item.id===recipe.id);if(source)setDeletingRecipe(source)}} className="text-[#b43d34] hover:bg-[#fff0ed] hover:text-[#9f3028]"><Trash2 size={15}/>Eliminar</Button></div>}</article>)}</div>:<div className="mt-3 rounded-3xl border border-dashed border-[#bfd0db] bg-white p-8 text-center"><Search className="mx-auto text-[#87a4b5]"/><p className="mt-3 font-bold">No hay coincidencias</p><button onClick={()=>setRecipeSearch("")} className="mt-2 text-sm font-bold text-[#087f8c]">Limpiar búsqueda</button></div>}
    </section>}
    {section==="equivalences"&&<section className="mt-5">
      <div className="rounded-3xl bg-gradient-to-br from-[#087f8c] to-[#12627a] p-5 text-white sm:p-6"><div className="flex flex-wrap items-end justify-between gap-4"><div><p className="text-xs font-bold tracking-widest text-white/70">PREPARACIÓN SIN CÁLCULOS</p><h2 className="font-display mt-1 text-2xl font-bold">Tablas de equivalencias</h2><p className="mt-2 max-w-2xl text-sm leading-relaxed text-white/90">Guarda la proporción del envase una vez y consulta al instante cuánto producto corresponde a cada biberón de 30 a 300 ml.</p></div><Button onClick={()=>setEquivalenceDialogOpen(true)} className="bg-white text-[#08717c] shadow-sm hover:bg-[#f3fbfb]"><Plus size={18}/>Nueva equivalencia</Button></div></div>
      {equivalences.length?<div className="mt-4 grid gap-4 lg:grid-cols-2">{equivalences.map(item=><article key={item.id} className="overflow-hidden rounded-3xl border border-[#b9d6dc] bg-white shadow-sm"><div className="flex items-start justify-between gap-3 p-5"><div><div className="flex items-center gap-2"><span className="grid size-10 shrink-0 place-items-center rounded-xl bg-[#eaf7f6] text-[#087f8c]"><Calculator size={20}/></span><h3 className="font-display text-xl font-bold">{item.title}</h3></div><p className="mt-3 text-sm text-[#63798b]">Proporción original: <b className="text-[#17324d]">{quantityText(item.productAmount)} {item.productUnit}</b> por <b className="text-[#17324d]">{quantityText(item.milkMl)} ml</b> de leche</p></div><button aria-label={`Eliminar ${item.title}`} onClick={()=>setDeletingEquivalence(item)} className="grid size-9 shrink-0 place-items-center rounded-lg text-[#8a9aa6] transition hover:bg-[#fff0ed] hover:text-[#b43d34]"><Trash2 size={16}/></button></div><div className="border-t border-[#e4ecef]"><table className="w-full text-sm"><thead><tr className="bg-[#f3f8f9] text-left text-xs uppercase tracking-wide text-[#647b8c]"><th className="px-5 py-3 font-bold">Leche</th><th className="px-5 py-3 text-right font-bold">Producto</th></tr></thead><tbody>{bottleSizes.map((milk,index)=><tr key={milk} className={index%2?"bg-[#fafcfc]":"bg-white"}><td className="px-5 py-2.5 font-semibold text-[#466071]">{milk} ml</td><td className="px-5 py-2.5 text-right font-bold text-[#08717c]">{quantityText(item.productAmount*milk/item.milkMl)} {item.productUnit}</td></tr>)}</tbody></table></div></article>)}</div>:<div className="mt-4 rounded-3xl border border-dashed border-[#9ec8d1] bg-[#f8fcfc] p-8 text-center"><span className="mx-auto grid size-12 place-items-center rounded-2xl bg-[#eaf7f6] text-[#087f8c]"><Calculator size={24}/></span><h3 className="font-display mt-3 text-xl font-bold">Aún no hay equivalencias</h3><p className="mx-auto mt-1 max-w-md text-sm leading-relaxed text-[#708496]">Crea la primera con las cantidades que aparecen en el envase del producto.</p><Button onClick={()=>setEquivalenceDialogOpen(true)} className="mt-4 bg-[#087f8c] text-white hover:bg-[#066b76]"><Plus size={17}/>Crear la primera tabla</Button></div>}
    </section>}
    <AllergenDialog open={allergenDialogOpen} onOpenChange={setAllergenDialogOpen} onSave={saveAllergen}/>
    <ExposureDatesDialog open={!!editingDates} allergen={editingDates} records={editingDates?childExposures.filter(item=>item.allergenId===editingDates.id).sort((a,b)=>a.dayIndex-b.dayIndex):[]} onOpenChange={open=>{if(!open)setEditingDates(null)}} onSave={saveExposureDates}/>
    <AlertDialog open={!!deletingAllergen} onOpenChange={open=>{if(!open&&!deletingAllergenBusy)setDeletingAllergen(null)}}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>¿Eliminar “{deletingAllergen?.name}”?</AlertDialogTitle><AlertDialogDescription>Se quitará del catálogo familiar y también se eliminarán sus checks de los tres días en todos los perfiles. Esta acción no se puede deshacer.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel disabled={deletingAllergenBusy}>Cancelar</AlertDialogCancel><AlertDialogAction variant="destructive" disabled={deletingAllergenBusy} onClick={event=>{event.preventDefault();void deleteAllergen()}}>{deletingAllergenBusy?"Eliminando…":"Eliminar alimento"}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
    <RecipeDialog open={recipeDialogOpen} recipe={editingRecipe} onOpenChange={setRecipeDialogOpen} onSave={saveRecipe}/>
    <AlertDialog open={!!deletingRecipe} onOpenChange={open=>{if(!open&&!deleting)setDeletingRecipe(null)}}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>¿Eliminar “{deletingRecipe?.title}”?</AlertDialogTitle><AlertDialogDescription>La receta se quitará de tu recetario familiar y dejará de aparecer en todos los perfiles.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel disabled={deleting}>Cancelar</AlertDialogCancel><AlertDialogAction variant="destructive" disabled={deleting} onClick={event=>{event.preventDefault();void deleteRecipe()}}>{deleting?"Eliminando…":"Eliminar receta"}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
    <EquivalenceDialog open={equivalenceDialogOpen} onOpenChange={setEquivalenceDialogOpen} onSave={saveEquivalence}/>
    <AlertDialog open={!!deletingEquivalence} onOpenChange={open=>{if(!open&&!deletingEquivalenceBusy)setDeletingEquivalence(null)}}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>¿Eliminar “{deletingEquivalence?.title}”?</AlertDialogTitle><AlertDialogDescription>La tabla dejará de estar disponible para todos los perfiles.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel disabled={deletingEquivalenceBusy}>Cancelar</AlertDialogCancel><AlertDialogAction variant="destructive" disabled={deletingEquivalenceBusy} onClick={event=>{event.preventDefault();void deleteEquivalence()}}>{deletingEquivalenceBusy?"Eliminando…":"Eliminar equivalencia"}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
  </div>
}
